        entries = self._rates.get((src, dst))
        if not entries or on not in entries:
            raise CurrencyError("no rate %s -> %s set on %s" % (src, dst, on.isoformat()))
        del entries[on]
        self._days[(src, dst)].remove(on)
        if not entries:
            del self._rates[(src, dst)]
            del self._days[(src, dst)]
